static void vivid_update_format_cap_sync_strides(struct vivid_dev *dev)
{
	unsigned int p;

	for (p = 0; p < tpg_g_buffers(&dev->tpg); p++) {
		unsigned int stride = tpg_g_line_width(&dev->tpg, p);
		unsigned int min_stride = (dev->fmt_cap_rect.width *
					   dev->fmt_cap->bit_depth[p]) >> 3;

		if (stride < min_stride)
			tpg_s_bytesperline(&dev->tpg, p, min_stride);
	}
}

